<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user=app_require_permission('catering.view');$canManage=app_has_permission('catering.manage',$user);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Catering Pipeline</title><style>
:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6d716b;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--shadow:0 15px 40px rgba(25,26,22,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.topbar{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:12px}.logo{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:var(--dark);color:#fff;font-weight:900}.brand strong{display:block}.brand small{display:block;color:var(--muted)}.actions{display:flex;gap:8px}.btn{min-height:38px;border:1px solid var(--line);border-radius:10px;padding:8px 12px;background:#fff;color:var(--ink);font-weight:800;text-decoration:none}.btn.primary{border-color:var(--accent);background:var(--accent);color:#fff}.shell{padding:24px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:18px}.head h1{margin:4px 0 0;font-size:38px;letter-spacing:-.05em}.eyebrow{margin:0;color:var(--accent);font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.13em}.head p:last-child{max-width:780px;margin:8px 0 0;color:var(--muted)}.summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:16px}.kpi{padding:14px;border:1px solid var(--line);border-radius:16px;background:#fff}.kpi small{display:block;color:var(--muted);font-size:9px;font-weight:900;text-transform:uppercase}.kpi strong{display:block;margin-top:6px;font-size:26px}.toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 200px auto;gap:8px;margin-bottom:15px}.field{width:100%;min-height:40px;border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#fff}.board-wrap{overflow:auto;padding-bottom:24px}.board{display:grid;grid-template-columns:repeat(10,minmax(250px,1fr));gap:12px;min-width:2600px;align-items:start}.column{min-height:390px;padding:10px;border:1px solid var(--line);border-radius:16px;background:#e9e8e4}.column.drag-over{outline:3px solid rgba(217,74,43,.25)}.column-head{display:flex;align-items:center;justify-content:space-between;padding:5px 5px 10px}.column-head strong{text-transform:capitalize;font-size:12px}.column-head span{min-width:25px;padding:4px 7px;border-radius:999px;background:#fff;text-align:center;font-size:10px;font-weight:900}.cards{display:grid;gap:8px}.lead-card{padding:13px;border:1px solid #d8d8d2;border-radius:13px;background:#fff;box-shadow:0 5px 14px rgba(25,26,22,.04);cursor:pointer}.lead-card[draggable="true"]{cursor:grab}.lead-card h3{margin:0 0 5px;font-size:14px}.lead-card p{margin:0;color:var(--muted);font-size:10px;line-height:1.45}.event-line{margin-top:8px;font-size:10px;font-weight:800}.chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.chip{padding:4px 6px;border-radius:999px;background:#f1f0ec;color:#5f635d;font-size:8px;font-weight:900}.lead-meta{display:flex;justify-content:space-between;gap:8px;margin-top:10px;padding-top:9px;border-top:1px solid #ecece8;font-size:9px;color:var(--muted)}.empty{padding:28px 10px;text-align:center;color:#8b8e89;font-size:11px;border:1px dashed #c9c9c2;border-radius:12px}.drawer{position:fixed;top:0;right:-620px;width:min(600px,96vw);height:100vh;z-index:50;background:#fff;border-left:1px solid var(--line);box-shadow:-20px 0 50px rgba(0,0,0,.14);transition:.2s;overflow:auto}.drawer.open{right:0}.drawer-head{position:sticky;top:0;display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:20px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.97);backdrop-filter:blur(10px);z-index:2}.drawer-head h2{margin:5px 0 0;font-size:25px}.drawer-body{padding:20px}.close{border:0;background:#f1f1ee;width:38px;height:38px;border-radius:10px;font-size:20px}.detail-grid,.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.detail{padding:10px;border-radius:11px;background:#f6f5f2}.detail small{display:block;color:var(--muted);font-size:8px;font-weight:900;text-transform:uppercase}.detail strong{display:block;margin-top:4px;font-size:11px;line-height:1.4;word-break:break-word}.wide{grid-column:1/-1}.section{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.section h3{margin:0 0 10px;font-size:14px}.activity-list{display:grid;gap:8px}.activity{padding:10px;border:1px solid var(--line);border-radius:11px}.activity strong{font-size:10px}.activity p{margin:4px 0 0;color:var(--muted);font-size:10px;line-height:1.45}.activity small{display:block;margin-top:5px;color:#8a8d87;font-size:8px}.toast{position:fixed;right:20px;bottom:20px;z-index:80;padding:11px 14px;border-radius:11px;background:#171b1a;color:#fff;font-size:11px;box-shadow:var(--shadow)}.hidden{display:none}@media(max-width:850px){.summary{grid-template-columns:1fr 1fr}.toolbar{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}.detail-grid,.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><header class="topbar"><div class="brand"><div class="logo">G</div><div><strong>Catering Pipeline</strong><small>Restaurant AI events workspace</small></div></div><div class="actions"><a class="btn" href="catering.php" target="_blank">Public Form ↗</a><a class="btn" href="index.php">Workspace</a></div></header>
<main class="shell"><div class="head"><div><p class="eyebrow">Events & catering</p><h1>Catering pipeline</h1><p>Every public catering inquiry lands here. Qualify the event, plan menus and tastings, quote, contract, collect deposits, confirm operations, and preserve the full event history for the Restaurant Agent.</p></div><button class="btn primary" id="refresh">Refresh pipeline</button></div><div class="summary"><div class="kpi"><small>Open opportunities</small><strong id="openCount">0</strong></div><div class="kpi"><small>Pipeline value</small><strong id="pipelineValue">$0</strong></div><div class="kpi"><small>Weighted value</small><strong id="weightedValue">$0</strong></div><div class="kpi"><small>Next 30 days</small><strong id="upcomingCount">0</strong></div><div class="kpi"><small>Confirmed</small><strong id="confirmedCount">0</strong></div></div><div class="toolbar"><input class="field" id="search" placeholder="Search company, contact, event, venue, menu, notes..."><select class="field" id="stageFilter"><option value="">All stages</option></select><button class="btn" id="clearSearch">Clear</button></div><div class="board-wrap"><div class="board" id="board"></div></div></main>
<aside class="drawer" id="drawer"><div class="drawer-head"><div><p class="eyebrow">Catering opportunity</p><h2 id="drawerTitle">Event</h2></div><button class="close" id="drawerClose">×</button></div><div class="drawer-body" id="drawerBody"></div></aside><div class="toast hidden" id="toast"></div>
<script>window.CATERING_CONFIG={csrf:<?= json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,canManage:<?= $canManage?'true':'false' ?>};</script><script>
(()=>{const cfg=window.CATERING_CONFIG,stages=['new','qualified','menu_proposal','tasting','quoted','contracted','deposit_paid','confirmed','completed','lost'],labels={new:'New',qualified:'Qualified',menu_proposal:'Menu Proposal',tasting:'Tasting',quoted:'Quoted',contracted:'Contracted',deposit_paid:'Deposit Paid',confirmed:'Confirmed',completed:'Completed',lost:'Lost'};let leads=[],users=[],activeId='';const esc=v=>String(v??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));const money=v=>'$'+Number(v||0).toLocaleString(undefined,{maximumFractionDigits:0});const label=s=>labels[s]||s.replaceAll('_',' ');const toast=t=>{const e=document.getElementById('toast');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),1800)};async function api(url,options={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(options.headers||{})},...options});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed.');return d}
async function load(){const [list,summary]=await Promise.all([api('api/catering.php?action=list'),api('api/catering.php?action=summary')]);leads=list.leads||[];users=summary.users||[];renderSummary(summary.summary||[],summary.upcoming||[]);renderBoard();if(activeId)openLead(activeId)}
function renderSummary(rows,upcoming){const by=Object.fromEntries(rows.map(r=>[r.pipeline_stage,r]));const open=stages.filter(s=>!['completed','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.lead_count||0),0),value=stages.filter(s=>!['completed','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.value_total||0),0),weighted=stages.filter(s=>!['completed','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.weighted_value||0),0);document.getElementById('openCount').textContent=open;document.getElementById('pipelineValue').textContent=money(value);document.getElementById('weightedValue').textContent=money(weighted);document.getElementById('upcomingCount').textContent=upcoming.length;document.getElementById('confirmedCount').textContent=Number(by.confirmed?.lead_count||0)}
function renderBoard(){const q=document.getElementById('search').value.trim().toLowerCase(),filter=document.getElementById('stageFilter').value,filtered=leads.filter(l=>(!filter||l.stage===filter)&&(!q||[l.companyName,l.contactName,l.email,l.eventType,l.venueName,l.menuInterests,l.notes].join(' ').toLowerCase().includes(q)));document.getElementById('board').innerHTML=stages.map(stage=>{const items=filtered.filter(l=>l.stage===stage);return `<section class="column" data-stage="${stage}"><div class="column-head"><strong>${label(stage)}</strong><span>${items.length}</span></div><div class="cards">${items.length?items.map(card).join(''):'<div class="empty">No events</div>'}</div></section>`}).join('');document.querySelectorAll('.lead-card').forEach(card=>{card.addEventListener('click',()=>openLead(card.dataset.id));if(cfg.canManage)card.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',card.dataset.id))});if(cfg.canManage)document.querySelectorAll('.column').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over')});col.addEventListener('dragleave',()=>col.classList.remove('drag-over'));col.addEventListener('drop',async e=>{e.preventDefault();col.classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain');if(id)await moveStage(id,col.dataset.stage)})})}
function card(l){const title=l.companyName||l.contactName,chips=[l.eventType,l.serviceStyle,l.guestCount?`${l.guestCount} guests`:''].filter(Boolean);return `<article class="lead-card" data-id="${esc(l.id)}" draggable="${cfg.canManage?'true':'false'}"><h3>${esc(title)}</h3><p>${esc(l.contactName)} · ${esc(l.venueName||l.email)}</p><div class="event-line">${esc(l.eventDate||'Date TBD')}${l.startTime?' · '+esc(String(l.startTime).slice(0,5)):''}</div><div class="chips">${chips.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}</div><div class="lead-meta"><span>${l.estimatedValue!=null?money(l.estimatedValue):'Value TBD'}</span><span>${l.probability}%</span></div></article>`}
async function moveStage(id,stage){await api('api/catering.php',{method:'POST',body:JSON.stringify({action:'stage',id,stage,csrf_token:cfg.csrf})});toast('Stage updated');await load()}
async function openLead(id){activeId=id;const d=await api('api/catering.php?action=detail&id='+encodeURIComponent(id)),l=d.lead;document.getElementById('drawerTitle').textContent=l.companyName||l.contactName;document.getElementById('drawer').classList.add('open');document.getElementById('drawerBody').innerHTML=`<div class="detail-grid">${[['Contact',l.contactName],['Email',l.email],['Phone',l.phone||'—'],['Event',l.eventType],['Date',l.eventDate||'TBD'],['Time',[l.startTime,l.endTime].filter(Boolean).map(x=>String(x).slice(0,5)).join(' – ')||'TBD'],['Guests',l.guestCount||'TBD'],['Venue',l.venueName||'TBD'],['Address',l.venueAddress||'TBD'],['Service',l.serviceStyle||l.fulfillmentPreference||'TBD'],['Budget',l.budgetRange||'TBD'],['Assigned',l.assignedName||'Unassigned']].map(x=>`<div class="detail"><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join('')}</div><div class="section"><h3>Menu & operations</h3><p style="white-space:pre-wrap;color:var(--muted);font-size:12px;line-height:1.55"><strong>Menu:</strong> ${esc(l.menuInterests||'Not recorded')}\n\n<strong>Dietary:</strong> ${esc(l.dietaryRequirements||'None recorded')}\n\n<strong>Beverage:</strong> ${esc(l.beverageService||'Not recorded')}\n<strong>Staffing:</strong> ${esc(l.staffingNeeds||'Not recorded')}\n<strong>Rentals:</strong> ${esc(l.rentalsNeeds||'Not recorded')}</p></div>${cfg.canManage?editForm(l):''}<div class="section"><h3>Activity history</h3>${cfg.canManage?activityForm():''}<div class="activity-list" style="margin-top:10px">${(d.activities||[]).length?(d.activities||[]).map(a=>`<article class="activity"><strong>${esc(a.activity_type)} · ${esc(a.summary)}</strong>${a.details?`<p>${esc(a.details)}</p>`:''}<small>${esc(a.created_at)}${a.createdByName?' · '+esc(a.createdByName):''}</small></article>`).join(''):'<div class="empty">No activity yet.</div>'}</div></div>`;if(cfg.canManage)bindDrawer(l)}
function editForm(l){return `<div class="section"><h3>Event & pipeline controls</h3><div class="form-grid"><div><small>Stage</small><select class="field" id="fStage">${stages.map(s=>`<option value="${s}" ${s===l.stage?'selected':''}>${label(s)}</option>`).join('')}</select></div><div><small>Assigned to</small><select class="field" id="fAssigned"><option value="">Unassigned</option>${users.map(u=>`<option value="${u.id}" ${Number(l.assignedTo)===Number(u.id)?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></div><div><small>Event date</small><input class="field" id="fDate" type="date" value="${esc(l.eventDate||'')}"></div><div><small>Guest count</small><input class="field" id="fGuests" type="number" min="1" max="10000" value="${esc(l.guestCount??'')}"></div><div><small>Estimated value</small><input class="field" id="fValue" type="number" min="0" step="0.01" value="${esc(l.estimatedValue??'')}"></div><div><small>Probability %</small><input class="field" id="fProbability" type="number" min="0" max="100" value="${esc(l.probability)}"></div><div class="wide"><small>Next follow-up</small><input class="field" id="fFollowup" type="datetime-local" value="${esc(l.nextFollowupAt?String(l.nextFollowupAt).replace(' ','T').slice(0,16):'')}"></div><div class="wide"><small>Menu interests</small><textarea class="field" id="fMenu" rows="3">${esc(l.menuInterests)}</textarea></div><div class="wide"><small>Dietary requirements</small><textarea class="field" id="fDietary" rows="2">${esc(l.dietaryRequirements)}</textarea></div><div class="wide"><small>Internal / event notes</small><textarea class="field" id="fNotes" rows="4">${esc(l.notes)}</textarea></div><div class="wide"><small>Loss reason</small><input class="field" id="fLoss" value="${esc(l.lossReason)}"></div></div><div style="display:flex;gap:8px;margin-top:10px"><button class="btn primary" id="saveLead">Save</button><button class="btn" id="archiveLead">Archive</button></div></div>`}
function activityForm(){return `<div class="form-grid"><select class="field" id="aType"><option>note</option><option>call</option><option>email</option><option>meeting</option><option>site_visit</option><option>tasting</option><option>menu</option><option>quote</option><option>contract</option><option>deposit</option><option>followup</option><option>operations</option></select><input class="field" id="aSummary" placeholder="Activity summary"><textarea class="field wide" id="aDetails" rows="2" placeholder="Details"></textarea><button class="btn wide" id="addActivity">Add activity</button></div>`}
function bindDrawer(l){document.getElementById('fStage')?.addEventListener('change',e=>moveStage(l.id,e.target.value));document.getElementById('saveLead')?.addEventListener('click',async()=>{await api('api/catering.php',{method:'POST',body:JSON.stringify({action:'update',id:l.id,csrf_token:cfg.csrf,eventDate:document.getElementById('fDate').value,guestCount:document.getElementById('fGuests').value,estimatedValue:document.getElementById('fValue').value,probability:document.getElementById('fProbability').value,assignedTo:document.getElementById('fAssigned').value,nextFollowupAt:document.getElementById('fFollowup').value,menuInterests:document.getElementById('fMenu').value,dietaryRequirements:document.getElementById('fDietary').value,notes:document.getElementById('fNotes').value,lossReason:document.getElementById('fLoss').value})});toast('Event updated');await load()});document.getElementById('addActivity')?.addEventListener('click',async()=>{await api('api/catering.php',{method:'POST',body:JSON.stringify({action:'activity',id:l.id,csrf_token:cfg.csrf,activityType:document.getElementById('aType').value,summary:document.getElementById('aSummary').value,details:document.getElementById('aDetails').value})});toast('Activity added');await openLead(l.id)});document.getElementById('archiveLead')?.addEventListener('click',async()=>{if(!confirm('Archive this catering opportunity?'))return;await api('api/catering.php',{method:'POST',body:JSON.stringify({action:'archive',id:l.id,csrf_token:cfg.csrf})});activeId='';document.getElementById('drawer').classList.remove('open');await load()})}
const filter=document.getElementById('stageFilter');stages.forEach(s=>filter.insertAdjacentHTML('beforeend',`<option value="${s}">${label(s)}</option>`));document.getElementById('search').addEventListener('input',renderBoard);filter.addEventListener('change',renderBoard);document.getElementById('clearSearch').addEventListener('click',()=>{document.getElementById('search').value='';filter.value='';renderBoard()});document.getElementById('refresh').addEventListener('click',load);document.getElementById('drawerClose').addEventListener('click',()=>{activeId='';document.getElementById('drawer').classList.remove('open')});load().catch(e=>toast(e.message));})();
</script><script src="js/universal-admin-page-shell.js?v=20260915-1"></script>
</body></html>